<template><WorkspacePage title="定时任务" subtitle="维护任务配置、运行状态与调度记录"><a-form v-show="showSearch" class="query-form" layout="inline"><a-form-item label="任务名称"><a-input v-model:value="queryParams.jobName" allow-clear /></a-form-item><a-form-item label="任务组名"><a-select v-model:value="queryParams.jobGroup" allow-clear :options="groupOptions" /></a-form-item><a-form-item label="任务状态"><a-select v-model:value="queryParams.status" allow-clear :options="statusOptions" /></a-form-item><a-form-item><a-button type="primary" @click="handleQuery"><SearchOutlined />搜索</a-button><a-button @click="resetQuery"><ReloadOutlined />重置</a-button></a-form-item></a-form><div class="toolbar"><a-space wrap><a-button type="primary" @click="handleAdd" v-hasPermi="['monitor:job:add']"><PlusOutlined />新增</a-button><a-button :disabled="ids.length!==1" @click="handleUpdate()" v-hasPermi="['monitor:job:edit']"><EditOutlined />修改</a-button><a-button danger :disabled="!ids.length" @click="handleDelete()" v-hasPermi="['monitor:job:remove']"><DeleteOutlined />删除</a-button><a-button @click="handleExport" v-hasPermi="['monitor:job:export']"><DownloadOutlined />导出</a-button><a-button @click="handleJobLog({jobId:0})" v-hasPermi="['monitor:job:query']"><HistoryOutlined />日志</a-button></a-space><a-button shape="circle" @click="showSearch=!showSearch"><FilterOutlined /></a-button></div><ResourceTable :columns="columns" :rows="jobList" :loading="loading" :pagination="false" row-key="jobId" :scroll="{x:1100}"><template #headerCell="{column}"><a-checkbox v-if="column.key==='select'" :checked="allSelected" :indeterminate="ids.length>0&&!allSelected" @change="toggleAll" /></template><template #bodyCell="{column,record}"><template v-if="column.key==='select'"><a-checkbox :checked="ids.includes(record.jobId)" @change="e=>toggleRow(record,e.target.checked)" /></template><template v-else-if="column.key==='jobName'"><a-button type="link" @click="handleView(record)">{{record.jobName}}</a-button></template><template v-else-if="column.key==='jobGroup'"><dict-tag :options="sys_job_group" :value="record.jobGroup" /></template><template v-else-if="column.key==='status'"><a-switch v-model:checked="record.status" checked-value="0" un-checked-value="1" @change="()=>handleStatusChange(record)" /></template><template v-else-if="column.key==='actions'"><a-space><a-tooltip title="修改"><a-button type="link" @click="handleUpdate(record)" v-hasPermi="['monitor:job:edit']"><EditOutlined /></a-button></a-tooltip><a-tooltip title="删除"><a-button type="link" danger @click="handleDelete(record)" v-hasPermi="['monitor:job:remove']"><DeleteOutlined /></a-button></a-tooltip><a-tooltip title="执行一次"><a-button type="link" @click="handleRun(record)" v-hasPermi="['monitor:job:changeStatus']"><CaretRightOutlined /></a-button></a-tooltip><a-tooltip title="调度日志"><a-button type="link" @click="handleJobLog(record)" v-hasPermi="['monitor:job:query']"><HistoryOutlined /></a-button></a-tooltip></a-space></template></template></ResourceTable><a-pagination v-if="total>0" v-model:current="queryParams.pageNum" v-model:page-size="queryParams.pageSize" :total="total" show-size-changer @change="getList"/>
<ResourceDrawer :open="open" :title="title" :width="820" destroy-on-close @close="cancel"><a-form ref="jobRef" :model="form" :rules="rules" layout="vertical"><a-form-item label="任务名称" name="jobName"><a-input v-model:value="form.jobName" /></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="任务分组" name="jobGroup"><a-select v-model:value="form.jobGroup" :options="groupOptions" /></a-form-item></a-col><a-col :span="12"><a-form-item label="任务执行器" name="jobExecutor"><a-select v-model:value="form.jobExecutor" :options="executorOptions" /></a-form-item></a-col></a-row><a-form-item label="调用目标字符串" name="invokeTarget"><a-input v-model:value="form.invokeTarget" /></a-form-item><a-form-item label="位置参数" name="jobArgs"><a-input v-model:value="form.jobArgs" /></a-form-item><a-form-item label="关键字参数" name="jobKwargs"><a-input v-model:value="form.jobKwargs" /></a-form-item><a-form-item label="cron表达式" name="cronExpression"><a-input v-model:value="form.cronExpression"><template #addonAfter><a-button type="link" @click="handleShowCron">生成表达式</a-button></template></a-input></a-form-item><a-form-item v-if="form.jobId!==undefined" label="状态"><a-radio-group v-model:value="form.status" :options="statusOptions" /></a-form-item><a-row :gutter="16"><a-col :span="12"><a-form-item label="执行策略" name="misfirePolicy"><a-radio-group v-model:value="form.misfirePolicy" button-style="solid"><a-radio-button value="1">立即执行</a-radio-button><a-radio-button value="2">执行一次</a-radio-button><a-radio-button value="3">放弃执行</a-radio-button></a-radio-group></a-form-item></a-col><a-col :span="12"><a-form-item label="是否并发" name="concurrent"><a-radio-group v-model:value="form.concurrent" button-style="solid"><a-radio-button value="0">允许</a-radio-button><a-radio-button value="1">禁止</a-radio-button></a-radio-group></a-form-item></a-col></a-row></a-form><template #footer><a-button @click="cancel">取消</a-button><a-button type="primary" @click="submitForm">确定</a-button></template></ResourceDrawer><a-modal v-model:open="openCron" title="Cron表达式生成器" destroy-on-close :footer="null"><Crontab @hide="openCron=false" @fill="crontabFill" :expression="expression" /></a-modal><JobDetail v-model:visible="openView" :row="form" type="job"/></WorkspacePage></template>
<script setup name="Job">
import{CaretRightOutlined,DeleteOutlined,DownloadOutlined,EditOutlined,FilterOutlined,HistoryOutlined,PlusOutlined,ReloadOutlined,SearchOutlined}from'@ant-design/icons-vue';import WorkspacePage from '@/components/Antd/WorkspacePage.vue';import ResourceTable from '@/components/Antd/ResourceTable.vue';import ResourceDrawer from '@/components/Antd/ResourceDrawer.vue';import feedback from '@/plugins/antdFeedback';import Crontab from '@/components/Crontab';import JobDetail from './detail.vue';import{listJob,getJob,delJob,addJob,updateJob,runJob,changeJobStatus}from'@/api/monitor/job'
const router=useRouter(),{proxy}=getCurrentInstance(),{sys_job_group,sys_job_status,sys_job_executor}=proxy.useDict('sys_job_group','sys_job_status','sys_job_executor');const jobList=ref([]),open=ref(false),loading=ref(true),showSearch=ref(true),ids=ref([]),total=ref(0),title=ref(''),openView=ref(false),openCron=ref(false),expression=ref(''),jobRef=ref();const queryParams=reactive({pageNum:1,pageSize:10,jobName:undefined,jobGroup:undefined,status:undefined}),form=reactive({});const rules={jobName:[{required:true,message:'任务名称不能为空'}],invokeTarget:[{required:true,message:'调用目标字符串不能为空'}],cronExpression:[{required:true,message:'cron执行表达式不能为空'}]};const options=o=>computed(()=>o.value.map(x=>({label:x.label,value:x.value})));const groupOptions=options(sys_job_group),statusOptions=options(sys_job_status),executorOptions=options(sys_job_executor);const allSelected=computed(()=>jobList.value.length>0&&jobList.value.every(x=>ids.value.includes(x.jobId)));const columns=[{title:'',key:'select',width:48},{title:'任务编号',dataIndex:'jobId',key:'jobId',width:90},{title:'任务名称',key:'jobName',ellipsis:true},{title:'任务组名',key:'jobGroup'},{title:'调用目标字符串',dataIndex:'invokeTarget',key:'invokeTarget',ellipsis:true},{title:'cron执行表达式',dataIndex:'cronExpression',key:'cronExpression',ellipsis:true},{title:'状态',key:'status',width:90},{title:'操作',key:'actions',width:190}]
async function getList(){loading.value=true;try{const r=await listJob(queryParams);jobList.value=r.rows;total.value=r.total;ids.value=[]}finally{loading.value=false}}function reset(){Object.keys(form).forEach((key)=>delete form[key]);Object.assign(form,{jobId:undefined,jobName:undefined,jobGroup:undefined,jobExecutor:undefined,invokeTarget:undefined,jobArgs:undefined,jobKwargs:undefined,cronExpression:undefined,misfirePolicy:'1',concurrent:'1',status:'1'});nextTick(()=>jobRef.value?.clearValidate())}function cancel(){open.value=false;reset()}function handleQuery(){queryParams.pageNum=1;getList()}function resetQuery(){Object.assign(queryParams,{pageNum:1,jobName:undefined,jobGroup:undefined,status:undefined});handleQuery()}function toggleRow(row,on){ids.value=on?[...new Set([...ids.value,row.jobId])]:ids.value.filter(x=>x!==row.jobId)}function toggleAll(e){ids.value=e.target.checked?jobList.value.map(x=>x.jobId):[]}async function handleStatusChange(row){const text=row.status==='0'?'启用':'停用';try{await feedback.confirm(`确认要"${text}""${row.jobName}"任务吗?`);await changeJobStatus(row.jobId,row.status);feedback.msgSuccess(`${text}成功`)}catch{row.status=row.status==='0'?'1':'0'}}async function handleRun(row){try{await feedback.confirm(`确认要立即执行一次"${row.jobName}"任务吗?`);await runJob(row.jobId,row.jobGroup);feedback.msgSuccess('执行成功')}catch{}}async function handleView(row){Object.assign(form,(await getJob(row.jobId)).data);openView.value=true}function handleShowCron(){expression.value=form.cronExpression;openCron.value=true}function crontabFill(value){form.cronExpression=value}function handleJobLog(row){router.push(`/monitor/job-log/index/${row.jobId||0}`)}function handleAdd(){reset();open.value=true;title.value='添加任务'}async function handleUpdate(row={}){reset();Object.assign(form,(await getJob(row.jobId||ids.value[0])).data);open.value=true;title.value='修改任务'}async function submitForm(){if(!await jobRef.value.validateFields().then(()=>true).catch(()=>false))return;const edit=form.jobId!==undefined;if(edit)await updateJob(form);else await addJob(form);feedback.msgSuccess(edit?'修改成功':'新增成功');open.value=false;getList()}async function handleDelete(row={}){try{const values=row.jobId||ids.value;await feedback.confirm(`是否确认删除定时任务编号为"${values}"的数据项?`);await delJob(values);feedback.msgSuccess('删除成功');getList()}catch{}}function handleExport(){proxy.download('monitor/job/export',{...queryParams},`job_${Date.now()}.xlsx`)}getList()
</script><style scoped>.query-form{padding:16px;margin-bottom:12px;border:1px solid var(--workspace-border)}.toolbar{display:flex;justify-content:space-between;margin-bottom:12px}:deep(.ant-pagination){justify-content:flex-end;margin-top:14px}</style>
